insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('n-descriptions', 'Add meta descriptions to 5 website pages', 'next', 'Audit', 'local, agent, license, recovery, dna-code.', 20);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('n-h1', 'Add a main heading to /downloads in the app', 'next', 'Audit', '', 21);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('n-csp', 'Enforce the app''s Content Security Policy', 'next', 'Audit', 'It is report-only today; the csp-enforce-public branch exists.', 22);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('n-sitemap', 'Publish a sitemap for the app', 'next', 'Audit', '', 23);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('n-previews', 'Add canonical addresses and link previews', 'next', 'Audit', 'Low priority; every page lacks them.', 24);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('n-egress', 'Review refused egress requests each month', 'next', 'Google Cloud', 'A BigQuery query in docs/gcp-observability.md shows which hosts visitors ask for.', 25);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('l-failover', 'Put the failover Worker on the live route', 'later', 'Website', 'Written and tested. Use fail-open routing; test on a separate address first.', 26);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('l-xrpl', 'Anchor Merkle roots on the XRPL', 'later', 'Chain', 'Needs a wallet secret stored as a Cloudflare secret, never pasted in chat.', 27);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('l-vault', 'Personal-data vault with grants', 'later', 'Privacy', 'Not started. Personal data stays on the owner''s computer until then.', 28);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('p-signups', 'Open sign-ups', 'paused', 'RabbitOS', 'Stays off in Supabase until the live checks pass.', 29);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('p-k8s', 'Kubernetes cluster', 'paused', 'Google Cloud', 'Optional. Cloud Run covers the needs today; Setup-GcpGke.ps1 is ready.', 30);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('d-research-tools', 'Research tools in the hub: research_sources and research_search', 'done', 'Research', 'Code and tests are done (PubMed, Europe PMC, ClinicalTrials.gov, openFDA). Live after the hub is redeployed.', 31);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('d-miner-job', 'Cloud miner, adopt and research loop written and tested', 'done', 'Chain', 'Scheduled sync (30 min) and task worker (5 min) run on your PC; the cloud miner waits for its secret step.', 32);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('d-backup-job', 'Cloud backup job written and tested', 'done', 'Google Cloud', 'Supabase dump and Cloudflare D1, KV, R2 as a Cloud Run job; offline tests pass.', 33);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('d-help-catalog', 'Every platform command recorded in the catalog, with hub_help for workers', 'done', 'Assistants', '190 commands (36 guest, 154 owner): Google Cloud setup with previews, hub keys, tests, read-only hub calls. hub_help explains services, tools, shells, agents and troubleshooting. Live after the hub is redeployed.', 34);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('w-miner-secret', 'Set up the cloud miner', 'waiting', 'You', 'Run Setup-GcpMinerSecrets.ps1 yourself (the ingest secret), then Setup-GcpMinerJob.ps1 -RunNow, then Test-CloudMiner.ps1.', 35);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('w-backup-job', 'Set up the cloud backup job', 'waiting', 'You', 'Run Setup-GcpBackupJob.ps1 -WhatIf, then for real. It copies the Supabase URL and a read-only Cloudflare token into Secret Manager. Keep the local backup until a cloud run is compared with it.', 36);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('w-hub-redeploy', 'Redeploy the hub so research_search goes live', 'waiting', 'You', 'Run Setup-GcpHub.ps1 (publishes research_search, hub_help and the new command catalog). The hub is on Google Cloud, so this needs your go-ahead.', 37);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('n-live-more', 'Live search for NIH RePORTER and ClinVar', 'next', 'Research', 'RePORTER needs a POST; ClinVar needs its own response shape. Both are already used by the owner''s agents.', 38);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('n-ingest-proposals', 'Let a live search propose an ingest task', 'next', 'Research', 'The tasks page already takes proposals; a person approves before the owner''s agents fetch and store anything.', 39);
